<?php require dirname(__DIR__).'/includes/bootstrap.php';$u=require_role(['ADMIN']);page_start('Tổng quan showroom','Theo dõi hoạt động và quản lý dữ liệu bán hàng.');if(!empty($_SESSION['recovery_once'])){notice('Lưu các mã khôi phục này ở nơi riêng tư. Mỗi mã chỉ dùng một lần và chỉ hiển thị trong lần này.');echo '<div class="panel"><code>'.e(implode(' · ',$_SESSION['recovery_once'])).'</code></div>';unset($_SESSION['recovery_once']);}$counts=db_one("SELECT (SELECT COUNT(*) FROM xe WHERE trang_thai='SAN_SANG_BAN') ton,(SELECT COUNT(*) FROM hop_dong WHERE trang_thai_hd='CHO_COC') coc,(SELECT COUNT(*) FROM hop_dong WHERE trang_thai_hd='CHO_XU_LY') xu_ly,(SELECT COUNT(*) FROM lich_hen WHERE trang_thai='CHO_XAC_NHAN') lich");echo '<div class="stats">';foreach(['ton'=>'Xe sẵn sàng','coc'=>'Đơn chờ cọc','xu_ly'=>'Cần đối soát','lich'=>'Lịch chờ xác nhận']as$k=>$label)echo '<div class="stat"><span>'.e($label).'</span><b>'.(int)$counts[$k].'</b></div>';echo '</div><div class="grid">';foreach(['hang_xe'=>'Hãng xe','dong_xe'=>'Dòng xe','cau_hinh'=>'Phiên bản','kho_xe'=>'Kho VIN','showroom'=>'Showroom','khuyen_mai'=>'Khuyến mãi','tai_khoan'=>'Tài khoản / phân quyền','noi_dung'=>'Nội dung website','bao_cao'=>'Báo cáo','chi_tien'=>'Chi tiền thực tế','cau_hinh_he_thong'=>'Tích hợp / VNPay','nhat_ky'=>'Nhật ký thao tác']as$p=>$label)echo '<a class="card" href="'.e(url('admin/'.$p.'.php')).'"><h3>'.e($label).' →</h3></a>';echo '</div>';page_end();
